ee:variables.ee:set-variable:
output application/json
---
{
	"method": "POST",
	"host": Mule::p('linka.host'),
	"port": Mule::p('linka.port'),
	"path": Mule::p('linka.path.token'),
	"basePath": Mule::p('linka.basePath'),
	"queryParams": {
		"key": Mule::p('secure::linka.username'),
		"value": Mule::p('secure::linka.password')
	}
}

set-variable.value:
#[output application/json
---
{
	"method": "GET",
	"host": Mule::p('linka.host'),
	"port": Mule::p('linka.port'),
	"path": Mule::p('linka.path.invoices'),
	"basePath": Mule::p('linka.basePath'),
	"queryParams": {
		"issue_date": "24-07-2025",
		//"reception_date": "24-07-2025",//now() as String{format: "dd-MM-YYYY"},
		//"eval_status": "1"
	},
	"headers": {
		"Authorization": "Bearer " ++ payload.access
	}
}]

logger.message:
#[output application/json
---
{
	"correlationId": vars.correlationId,
	"message": "No invoices received from linka"
}]

set-variable.value:
#[output application/json
---
{
	"method": "GET",
	"host": Mule::p('linka.host'),
	"port": Mule::p('linka.port'),
	"path": Mule::p('linka.path.file'),
	"basePath": Mule::p('linka.basePath'),
	"uriParams": vars.dbOperation.fileID ,
	"headers": {
		"Authorization": "Bearer " ++ payload.access
	}
}]

logger.message:
#[output application/json
---
{
	"correlationId": vars.correlationId,
	"message": "Invoice has already been inserted"
}]
